sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === "") return;
    g_form.getReference("student", function(student) {
        if (!student) return;
        if (student.annual_family_income) g_form.setValue("annual_family_income", student.annual_family_income);
        if (student.course) g_form.setValue("course", student.course);
        if (student.category) g_form.setValue("category", student.category);
        if (student.cgpa) {
            var val = parseFloat(student.cgpa);
            if (!isNaN(val)) {
                var perc = (val <= 10) ? (val * 9.5).toFixed(2) : val.toFixed(2);
                g_form.setValue("academic_percentage", perc);
            }
        }
    });
}
